/// <summary>
/// MPJ_5013_ExciseRegisterEntry
/// </summary>
public class METNat3040RegisterUpdateUIBuilder  extends SysOperationAutomaticUIBuilder
{
    private DialogField dialogUpdateNat3040,dialogNat3040Number;
    private METNat3040RegisterUpdateContract metNat3040RegisterUpdateContract;

}

Method.Source:
    /// <summary>
    /// Override the standard behavior to disable NAT3040Number input field when we are updating the NAT3040 number
    /// </summary>
    public void postBuild()
    {
        super();

        // get datacontract
        metNat3040RegisterUpdateContract = this.dataContractObject();

        // get dialog fields
        dialogUpdateNat3040 = this.bindInfo().getDialogField(metNat3040RegisterUpdateContract, methodstr(METNat3040RegisterUpdateContract, parmUpdateNat3040));
        dialogNat3040Number = this.bindInfo().getDialogField(metNat3040RegisterUpdateContract, methodstr(METNat3040RegisterUpdateContract, parmNat3040Number));

        // register override methods
        dialogUpdateNat3040.registerOverrideMethod(methodstr(FormCheckBoxControl, modified), methodstr(METNat3040RegisterUpdateUIBuilder, allowNAT3040NumberInput), this);

        // enable/disable transdate based on checkbox
        dialogNat3040Number.enabled(!any2enum(dialogUpdateNat3040.value()));
    }

/// <summary>
/// Enable or Disable the NAT3040Number input textbox
/// </summary>
/// <param name = "_checkBoxControl">checkbox control which controls the NAT3040number input field</param>
/// <returns>true always</returns>
public boolean allowNAT3040NumberInput(FormCheckBoxControl _checkBoxControl)
{
    // set enabled or disabled based on checkbox
    dialogNat3040Number.enabled(!_checkBoxControl.checked());
    
    return true;
}
